import json
from fnmatch import fnmatchcase


def as_list(value):
    return value if isinstance(value, list) else [value]


def grants(statement, action):
    return any(fnmatchcase(action.lower(), str(a).lower()) for a in as_list(statement.get("Action", [])))


def service_may(document, service, action, source_arn):
    # An Allow statement for this service principal and action, conditioned on source_arn.
    for st in as_list(json.loads(document).get("Statement", [])):
        principal = st.get("Principal")
        if st.get("Effect") != "Allow" or not isinstance(principal, dict):
            continue
        if service in as_list(principal.get("Service", [])) and grants(st, action):
            if source_arn in json.dumps(st.get("Condition", {})):
                return True
    return False

def topic_arn(sns, topic_name):
    arns = [t["TopicArn"] for t in sns.list_topics()["Topics"] if t["TopicArn"].split(":")[-1] == topic_name]
    assert len(arns) == 1, f"no SNS topic named {topic_name}"
    return arns[0]

s3 = session.client("s3")
sns = session.client("sns")
bucket = "invoice-archive-7310"
assert bucket in [b["Name"] for b in s3.list_buckets()["Buckets"]], "no bucket named invoice-archive-7310"
topic = topic_arn(sns, "archive-deletions")
config = s3.get_bucket_notification_configuration(Bucket=bucket)
events = [e for t in config.get("TopicConfigurations", []) if t["TopicArn"] == topic for e in t["Events"]]
assert "s3:ObjectRemoved:*" in events, f"the bucket sends these events to the topic: {events}"
policy = sns.get_topic_attributes(TopicArn=topic)["Attributes"].get("Policy")
assert policy, "the topic has no access policy"
assert service_may(policy, "s3.amazonaws.com", "sns:Publish", "arn:aws:s3:::" + bucket), (
    "the topic policy does not let S3 publish on behalf of the bucket"
)

